// n8n Code node — Run Once for All Items
const urlRegex = /\b(?:https?:\/\/)?(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}(?:\/[^\s]*)?/gi;
const out = [];
const seen = new Set();
for (const item of $input.all()) {
  const text = item.json.text ?? item.json.message?.text ?? '';  // handles both shapes
  const matches = text.match(urlRegex) || [];
  for (let u of matches) {
    u = u.replace(/[.,;:!?")\]]+$/, '');                // trailing punctuation
    if (!/^https?:\/\//i.test(u)) u = 'https://' + u;   // add scheme
    if (!seen.has(u)) {                                 // dedupe across the message
      seen.add(u);
      out.push({ json: { url: u } });
    }
  }
}
return out;

// Code node — Run Once for Each Item
// Classifies how well the redirect chain was resolved so the Tier 1 agent
// can apply its MISSING DATA rules instead of guessing (or asking).
const SHORTENERS = new Set([
  't.ly','bit.ly','tinyurl.com','goo.gl','ow.ly','is.gd','buff.ly','cutt.ly',
  'rb.gy','shorturl.at','tiny.cc','s.id','lnkd.in','rebrand.ly','t.co','v.gd',
  'qrco.de','u.to','2no.co','shorte.st','adf.ly','soo.gd','clck.ru','urlz.fr'
]);

// no URL global in the task-runner sandbox — extract host with a regex
function host(u) {
  if (!u) return '';
  return String(u).replace(/^https?:\/\//i, '').split(/[\/?#]/)[0].toLowerCase().replace(/^www\./, '');
}

const b = $json.body || {};
const original = b.requested_url || 'unknown';
const resolved = (b.success && b.resolved_url) ? b.resolved_url : '';

const oHost = host(original);
const rHost = host(resolved);

let status;
if (!resolved) {
  status = 'failed';               // unshortener returned nothing usable
} else if (SHORTENERS.has(rHost)) {
  status = 'partial';              // chained shortener — final destination still hidden
} else {
  status = 'full';                 // resolved to a real destination (or was a direct link)
}

return {
  json: {
    original_url: original,
    resolved_url: resolved,                    // may be '' — the agent prompt handles that
    unshortened_url: resolved || original,     // deepest URL we have; used for the VT lookup
    resolution_status: status,                 // 'full' | 'partial' | 'failed'
    original_is_shortener: SHORTENERS.has(oHost),
    unshorten_ok: !!b.success
  }
};

// Code node — Run Once for Each Item
const url = $json.unshortened_url; // deepest URL we could reach

const vtId = Buffer.from(url)
  .toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/, '');

return {
  json: {
    original_url: $json.original_url,
    resolved_url: $json.resolved_url,
    unshortened_url: url,
    resolution_status: $json.resolution_status,
    original_is_shortener: $json.original_is_shortener,
    vtId: vtId
  }
};

let t = ($input.first().json.output || '').trim();

// 0a. Salvage guard: if the model leaked reasoning before the caption,
// drop everything before the first verdict marker.
const verdictStart = t.search(/<b>|🔴|🟠|🟢|⚪/);
if (verdictStart > 0) t = t.slice(verdictStart).trim();

// 0b. Terminal fallback: raw model text must NEVER reach the family chat.
// If there is still no caption (e.g. the model asked for missing data),
// replace the whole thing with a safe inconclusive caption.
const FALLBACK = '<b>⚪ פסק דין: לא חד-משמעי</b>\n<b>המלצה:</b> לא הצלחנו לנתח את ההודעה הזו אוטומטית. מומלץ שלא ללחוץ על הקישור, לא למסור פרטים אישיים, ולאמת מול השולח רק דרך הערוצים הרשמיים.';
const hasCaption = t.startsWith('<b>') || /^(🔴|🟠|🟢|⚪)/.test(t);
const asksForData = /please provide|i need |i require|cannot complete|missing (the )?resolved_url/i.test(t);
if (!hasCaption || (asksForData && !t.startsWith('<b>'))) t = FALLBACK;

// 1. Protect the allowed tags by swapping them to placeholders
const allowed = ['b','/b','i','/i','code','/code'];
allowed.forEach((tag, idx) => {
  t = t.split(`<${tag}>`).join(`§§${idx}§§`);
});
// handle <a href="..."> and </a> too
t = t.replace(/<a href="([^"]*)">/g, '§§A§§$1§§/A§§').split('</a>').join('§§ENDA§§');

// 2. Escape everything else that Telegram could misread
t = t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// 3. Restore the real tags
allowed.forEach((tag, idx) => {
  t = t.split(`§§${idx}§§`).join(`<${tag}>`);
});
t = t.replace(/§§A§§([^§]*)§§\/A§§/g, '<a href="$1">').split('§§ENDA§§').join('</a>');

// WhatsApp copy: *bold*, _italic_, `code`, no HTML entities.
const caption_wa = t
  .replace(/<b>\s*([\s\S]*?)\s*<\/b>/g, (m, x) => (x ? '*' + x + '*' : ''))
  .replace(/<i>\s*([\s\S]*?)\s*<\/i>/g, (m, x) => (x ? '_' + x + '_' : ''))
  .replace(/<code>([\s\S]*?)<\/code>/g, '`$1`')
  .replace(/<a href="([^"]*)">([\s\S]*?)<\/a>/g, (m, href, label) => (label === href ? label : label + ' (' + href + ')'))
  .replace(/<[^>]+>/g, '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');

return [{ json: { caption: t, caption_wa } }];

// Family allowlist per channel.
// telegram: numeric user ids. whatsapp: international number, digits only
// (e.g. 9725XXXXXXXX), exactly as WhatsApp reports it.
const ALLOWED = {
  telegram: [11111111, 22222222, 33333333],
  whatsapp: ['9725XXXXXXX1', '9725XXXXXXX2'],
};
const r = $('Report').first().json;
const fromId = r.sender_id;
const isAllowed = (ALLOWED[r.channel] || []).map(String).includes(String(fromId));

return [{
  json: {
    text: r.text,
    channel: r.channel,
    isAllowed,
    fromId,
  },
}];

