// Family allowlist per channel.
// telegram: numeric user ids. whatsapp: international number, digits only
// (e.g. 9725XXXXXXXX), exactly as WhatsApp reports it.
const ALLOWED = {
  telegram: [11111111, 22222222, 33333333],
  whatsapp: ['9725XXXXXXX1', '9725XXXXXXX2'],
};
const r = $('Report').first().json;
const fromId = r.sender_id;
const isAllowed = (ALLOWED[r.channel] || []).map(String).includes(String(fromId));

return [{
  json: {
    text: r.text,
    channel: r.channel,
    isAllowed,
    fromId,
  },
}];

const text = ($input.first().json.text).toString().trim();

// 1. extract first URL-looking token from the message
let raw = (text.match(/(https?:\/\/\S+)|((www\.)?[a-z0-9-]+(\.[a-z0-9-]+)+(\/\S*)?)/i) || [])[0] || '';
if (!raw) throw new Error('No URL found in: ' + JSON.stringify(text));

// 2. clean trailing punctuation, add scheme if missing
raw = raw.replace(/[)\].,]+$/, '');
if (!/^https?:\/\//i.test(raw)) raw = 'https://' + raw;

// 3. manual parse (no URL global — task-runner sandbox safe)
const m = raw.match(/^(https?:\/\/)([^\/?#]+)([^?#]*)(\?[^#]*)?(#.*)?$/i);
if (!m) throw new Error('Could not parse: ' + raw);

let [, scheme, host, path = '', query = ''] = m;
const domain = host.replace(/^www\./i, '').toLowerCase();

// 4. SSRF guard — block internal hosts and bare IPs
const blocked = /^(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|169\.254\.|\[?::1|0\.0\.0\.0)/i;
if (blocked.test(domain) || /^\d+\.\d+\.\d+\.\d+$/.test(domain)) {
  throw new Error('Refusing to fetch internal/IP address: ' + domain);
}

// 5. strip tracking params
if (query) {
  const drop = ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','fbclid','gclid','ref'];
  const kept = query.slice(1).split('&').filter(kv => !drop.includes(kv.split('=')[0].toLowerCase()));
  query = kept.length ? '?' + kept.join('&') : '';
}

// 6. rebuild clean URL
const url = scheme.toLowerCase() + host + path + query;
return [{ json: { url, domain, original: text } }];

// Code node — "Signal Extractor" | Run Once for Each Item   [Tier A+]
const inp = $input.first().json;

// ── FAIL-CLOSED GUARD — a blocked or failed fetch must NEVER look like "no bad signals".
// "Fetch website HTML" runs with onError:continueRegularOutput, so a 429/403/timeout
// arrives here as { error: {...} } with no body. Without this guard every regex below
// runs against '' , returns false, scores 0, and the agent confidently reports 🟢 תקין
// on a page it never saw.
if (inp.error || (!inp.body && !inp.data)) {
  const nu = $('Normalize URL').first().json;
  return [{ json: {
    fetch_failed: true,
    domain: nu.domain || null,
    final_url: nu.url || null,
    http_status: inp.error?.status ?? inp.statusCode ?? null,
    reason: 'fetch failed (' + (inp.error?.status ?? 'empty body') + ')',
  }}];
}

// content-type guard — skip non-HTML (also surfaced as fetch_failed so the agent sees it)
const ctype = (inp.headers?.['content-type'] || '').toLowerCase();
if (ctype && !ctype.includes('text/html')) {
  const nu = $('Normalize URL').first().json;
  return [{ json: { fetch_failed: true, domain: nu.domain || null, final_url: nu.url || null,
    http_status: inp.statusCode ?? null,
    reason: 'not an HTML page (' + ctype + ')' } }];
}

// truncate before regex work (~500KB cap)
const html = (inp.body || inp.data || '').toString().slice(0, 500000);
const finalUrl = inp.url || $('Normalize URL').first().json.url;
const domain = (finalUrl.match(/^https?:\/\/(?:www\.)?([^\/?#]+)/i) || [])[1]?.toLowerCase() || '';

// ── VISIBLE-TEXT VIEW (Tier A). Strips <script>/<style>, all tags (which kills href and
// class attributes), percent-encoding and entities. Percent-encoded Hebrew is the big one:
// "%D7%99" literally contains the substring "99%", which made fake_stats fire on 12/12 of
// the documented cases. CONTENT signals read `text`; STRUCTURAL ones still read `html`.
const text = html
  .replace(/<(script|style|noscript|svg)\b[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/%[0-9A-Fa-f]{2}/g, ' ')
  .replace(/&[a-z]+;|&#\d+;/gi, ' ')
  .replace(/\s+/g, ' ');

const count  = re => (html.match(re) || []).length;   // structural (hrefs, asset paths)
const countT = re => (text.match(re) || []).length;   // content (what a human reads)
const grab   = re => (html.match(re) || [])[1] || null;

const urgencyHE = /(אחרון במלאי|יחידות אחרונות|נגמר המבצע|24 שעות|נשארו רק|מלאי אזל)/;
const urgencyEN = /(last units|almost gone|sale ends|only \d+ left|limited stock|selling fast)/i;

// fake_stats: a percentage must sit next to a CLAIM word, not just exist somewhere.
const CLAIM = '(?:הצלחה|מהלקוחות|מרוצים|יעילות|ממליצים|שביעות|דירוג|success|customers|satisfaction|effective|recommend|of users)';
// Count each percentage INDEPENDENTLY, asking whether a claim word sits within ~40 chars
// either side. A single greedy regex match would swallow two adjacent stats
// ("98% מהלקוחות מרוצים, 95% הצלחה") as ONE hit and never reach the >=2 threshold.
const CLAIM_RE = new RegExp(CLAIM, 'i');
const PCT_RE = /\b\d{2}(?:\.\d)? ?%/g;
let fakeStatsHits = 0;
for (let m; (m = PCT_RE.exec(text)) !== null; ) {
  const a = Math.max(0, m.index - 40);
  const b = Math.min(text.length, m.index + m[0].length + 40);
  if (CLAIM_RE.test(text.slice(a, b))) fakeStatsHits++;
}

// real_brands: word-boundaried — unbounded "g-star" was matching "rating-stars__label".
const BRANDS = "veja|allsaints|scotch|vagabond|carhartt|herschel|palladium|melissa|g-?star|levi'?s|nike|adidas|new balance|crocs";

// countdown_timer: the old urgency regex only caught Hebrew phrases and missed the actual
// clock widget ("00 ימים : 00 שעות"). Measured 5/12 on known-bad, 0 on the legit site.
const COUNTDOWN = /(?:\d{1,2}\s*(?:ימים|שעות|דקות|שניות)\s*[:：]\s*\d{1,2}|countdown|data-countdown)/i;

// paid_social_funnel: read off the ORIGINAL pasted URL, which still carries the ad-network
// parameters. Measured 10/12 on known-bad, 0 on the legit site — but legitimate retailers
// advertise too, so it is weighted as a supporting prior, never a conviction on its own.
const submitted = ($('Normalize URL').first().json.original || '') + ' ' + finalUrl;
const PAIDSOCIAL = /(fbclid=|utm_medium=paid|campaign_id=|ad_id=|tw_adid=|utm_source=(?:ig|facebook|tiktok))/i;

const signals = {
  domain,
  final_url: finalUrl,
  fetch_failed: false,
  product_title: grab(/og:title" content="([^"]+)/),
  price:    grab(/og:price:amount" content="([^"]+)/),
  currency: grab(/og:price:currency" content="([^"]+)/),

  // ── suspicious (dropshipping/scam) signals ──
  platform_shopify:    /cdn\/shop\/|myshopify|Shopify\.theme/i.test(html),
  ai_generated_images: /(Generated_Image|Gemini_Generated|dalle|midjourney|stable-?diffusion)/i.test(html),
  urgency:             urgencyHE.test(text) || urgencyEN.test(text),
  countdown_timer:     COUNTDOWN.test(text) || /countdown|data-countdown/i.test(html),
  paid_social_funnel:  PAIDSOCIAL.test(submitted),
  fake_stats:          fakeStatsHits >= 2,
  buy_x_get_x:         /(קנה \d+ קבל|buy \d+ get|1\+1|2\+2)/i.test(text),
  slow_shipping:       /(7-14|7–14|2-4 weeks|14 ימי עסקים)/i.test(text),
  trademark_on_brand:  /™/.test(text),
  whatsapp_only:       /(whatsapp|וואטסאפ|ווצאפ)/i.test(text),
  // only true TLDs, never matches .co.il or the word "online" in a domain name
  risky_tld:           /\.(shop|store|xyz|top|live|click|monster)$/i.test(domain) || /\.com\.co$/i.test(domain),
  payment_badge_spam:  countT(/(visa|mastercard|paypal|apple ?pay|google ?pay|maestro)/gi) >= 4,
  money_back_boiler:   /(60 ימי|ללא שאלות|no questions asked|שביעות רצון)/i.test(text),

  // ── legitimacy signals (reduce score) ──
  real_brands:     new RegExp('(?<![\\w-])(' + BRANDS + ')(?![\\w-])', 'i').test(text),
  physical_stores: /(החנויות שלנו|הסניפים שלנו|סניפים|כתובת החנות|our stores|store locator)/i.test(text),
  // /product/ (WooCommerce) as well as /products/ (Shopify)
  multi_product:   count(/\/products?\//g) > 20,
  // בע"מ with a straight quote, Hebrew gershayim ״, or a curly quote
  real_company_id: /(בע["״”]מ|ח\.פ|ע\.מ|company.?id)/i.test(text),
};

// weights: distinctive dropshipping signals dominate; commodity Shopify features near-zero
const w = {
  ai_generated_images: 30,   // strongest single tell
  fake_stats:          22,
  urgency:             15,
  trademark_on_brand:  15,
  countdown_timer:     15,
  slow_shipping:       12,
  buy_x_get_x:          8,
  risky_tld:            8,
  paid_social_funnel:   8,    // supporting prior only — legit retailers advertise too
  whatsapp_only:        4,    // weak — legit stores have WhatsApp too
  platform_shopify:     2,    // near-zero — everyone uses Shopify
  payment_badge_spam:   2,
  money_back_boiler:    2,
};
const rawScore = Object.keys(w).reduce((s, k) => s + (signals[k] ? w[k] : 0), 0);

// legitimacy offset — real retailer tells a dropshipper doesn't have
const legitOffset =
  (signals.real_brands     ? 25 : 0) +
  (signals.physical_stores ? 15 : 0) +
  (signals.multi_product   ? 15 : 0) +
  (signals.real_company_id ? 10 : 0);

signals.heuristic_score = Math.max(0, Math.min(rawScore - legitOffset, 100));
return [{ json: signals }];

// Code node — "Domain Age" | Run Once for Each Item   [Tier A+]
// Upstream "RDAP domain age" has fullResponse:true and onError:continueRegularOutput,
// so $json is { body, headers, statusCode } even on a 404.
const j = $json || {};
const tryParse = s => { try { return JSON.parse(s); } catch (e) { return null; } };

// FIX: rdap.org replies with Content-Type "application/rdap+json", which n8n does NOT
// always auto-parse as JSON. The old code handled `data`-as-string but never
// `body`-as-string, so a string body fell through to the fullResponse wrapper and
// age_days silently became null.
let body = {};
if (typeof j.body === 'string')                 body = tryParse(j.body) || {};
else if (j.body && typeof j.body === 'object')  body = j.body;
else if (typeof j.data === 'string')            body = tryParse(j.data) || {};
else if (j.data && typeof j.data === 'object')  body = j.data;
else if (Array.isArray(j.events) || j.ldhName)  body = j;   // already unwrapped

const status = j.statusCode ?? null;
const domain = ($('Signal Extractor').first().json.domain || '').toLowerCase();

// FIX: distinguish "this TLD publishes no RDAP" from "the lookup failed". .il has no RDAP
// service — rdap.org returns 404 for every .co.il domain, which is expected, not a failure.
const rdapUnsupportedTld = status === 404 && /\.il$/.test(domain);

const events  = body.events || [];
const reg     = events.find(e => e.eventAction === 'registration');
const regDate = reg?.eventDate || null;
const ageDays = regDate
  ? Math.floor((Date.now() - new Date(regDate).getTime()) / 86400000)
  : null;

return [{ json: {
  domain: body.ldhName || domain || null,
  registered: regDate,
  age_days: ageDays,
  age_known: ageDays !== null,
  rdap_unsupported_tld: rdapUnsupportedTld,
  rdap_status: status,
  young_domain: ageDays !== null && ageDays < 180   // strong scam signal
}}];

// Code node — "Parse VT" | Run Once for Each Item
const vt = $input.first().json.data.attributes;
const stats = vt.last_analysis_stats || {};

// carry forward the parsed age fields from the Domain Age code node
const prior = $('Code in JavaScript').first().json;

return [{ json: {
  ...prior,
  vt_malicious:  stats.malicious  ?? 0,
  vt_suspicious: stats.suspicious ?? 0,
  vt_harmless:   stats.harmless   ?? 0,
  vt_reputation: vt.reputation ?? null,
  vt_known: Object.keys(stats).length > 0,        // false if VT had no data / errored
}}];

let t = ($input.first().json.output || '').trim();

// 0a. Salvage guard: if the model leaked preamble/reasoning before the verdict
// caption, drop everything before the first verdict marker.
const verdictStart = t.search(/<b>|🎣|🔴|🟠|🟢|⚪/);
if (verdictStart > 0) t = t.slice(verdictStart).trim();

// 0b. Terminal fallback: raw model text must NEVER reach the family chat.
const FALLBACK = '<b>⚪ פסק דין: לא חד-משמעי</b>\n<b>המלצה:</b> לא הצלחנו לנתח את ההודעה הזו אוטומטית. מומלץ שלא ללחוץ על הקישור, לא למסור פרטים אישיים, ולאמת מול השולח רק דרך הערוצים הרשמיים.';
if (verdictStart === -1) t = FALLBACK;

// 1. Protect the allowed tags by swapping them to placeholders
const allowed = ['b','/b','i','/i','code','/code'];
allowed.forEach((tag, idx) => {
  t = t.split(`<${tag}>`).join(`§§${idx}§§`);
});
// handle <a href="..."> and </a> too
t = t.replace(/<a href="([^"]*)">/g, '§§A§§$1§§/A§§').split('</a>').join('§§ENDA§§');

// 2. Escape everything else that Telegram could misread
t = t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// 3. Restore the real tags
allowed.forEach((tag, idx) => {
  t = t.split(`§§${idx}§§`).join(`<${tag}>`);
});
t = t.replace(/§§A§§([^§]*)§§\/A§§/g, '<a href="$1">').split('§§ENDA§§').join('</a>');

// WhatsApp copy: *bold*, _italic_, `code`, no HTML entities.
const caption_wa = t
  .replace(/<b>\s*([\s\S]*?)\s*<\/b>/g, (m, x) => (x ? '*' + x + '*' : ''))
  .replace(/<i>\s*([\s\S]*?)\s*<\/i>/g, (m, x) => (x ? '_' + x + '_' : ''))
  .replace(/<code>([\s\S]*?)<\/code>/g, '`$1`')
  .replace(/<a href="([^"]*)">([\s\S]*?)<\/a>/g, (m, href, label) => (label === href ? label : label + ' (' + href + ')'))
  .replace(/<[^>]+>/g, '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');

return [{ json: { caption: t, caption_wa } }];

// Assemble a structured, research-ready case record (phishing/SMS branch).
const r = $('Report').first().json;
const urls = $('Create ID for VT').first().json;
const caption = $('Format output').first().json.caption || '';
const agentRaw = ($('Tier 1 Agent').first().json.output || '');

let vt = { known: false, malicious: null, suspicious: null, harmless: null, reputation: null };
try {
  const attrs = $('VirusTotal HTTP Request').first().json.data.attributes;
  const stats = attrs.last_analysis_stats || {};
  vt = {
    known: Object.keys(stats).length > 0,
    malicious: stats.malicious ?? 0,
    suspicious: stats.suspicious ?? 0,
    harmless: stats.harmless ?? 0,
    reputation: attrs.reputation ?? null,
  };
} catch (e) { /* VT errored or had no data — keep known:false */ }

const emoji = (caption.match(/🎣|🔴|🟠|🟢|⚪/) || ['⚪'])[0];
const MAP = { '🎣': 'phishing', '🔴': 'malicious', '🟠': 'suspicious', '🟢': 'clean', '⚪': 'inconclusive' };
const category = MAP[emoji];
const documentable = ['phishing', 'malicious', 'suspicious'].includes(category);

const deepest = urls.unshortened_url || urls.original_url || '';
